/**
 * The `seed` kind of resource: records generated by Seed, from a built-in
 * template or the objects, counts, field rules and relations the file gives.
 *
 * A seed resource is converted into a `SeedTemplate`, in list order, each
 * object's rules as the panel saves them, and held to Seed's own payload
 * schema and validator — checked by `seedTemplatePayloadSchema` as
 * `seed:execute` checks the panel's — so a refusal its run would meet after
 * its first objects were written is met before any.
 *
 * A relation whose parents are the records another resource of the file
 * created (`parents.from`) is kept apart from the template, as a draw: the
 * ids are known once that resource has run, and the environment hands them
 * to the seed as parents named by id (`records`), at most 2,000, the bound
 * of the parents a relation reads of the org. The template is checked with
 * such a relation in its place, its parents read of the org standing in.
 *
 * It runs `sandforge-seed`: a dry run and a run of the template the
 * environment converted from its file (`--template-file`), under the run id it
 * chose (`--run-id`); the removal of that run from the summary it printed,
 * and the preview of that removal (`--remove … --preview`).
 *
 * The answers are read with zod, off the shapes the script prints — its run
 * and dry-run summary (`main`), its preview (`removalPreviewJson`) — and an
 * answer that does not read as one is an error naming the script, never a
 * default: a plan that took a refusal it could not read for "nothing to do"
 * would apply over it.
 */

import { z } from 'zod';
import {
  PREBUILT_SEED_TEMPLATES,
  SEED_RELATION_LIMITS,
  seedDependencies,
  type EnvDocumentPath,
  type EnvSeedDraw,
  type EnvSeedParents,
  type EnvSeedResource,
  type EnvSeedRun,
  type SeedRelation,
  type SeedTemplate,
} from '@sandforge/shared';
import { seedTemplatePayloadSchema } from '../../../src/bridge/validatePayload.js';
import { LOCALE_DATA } from '../../../src/modules/seed/LocaleData.js';
import { SeedValidator } from '../../../src/modules/seed/SeedValidator.js';
import type { RunnableScript } from '../../scriptRunner.js';
import {
  countSchema,
  idSchema,
  readAnswer,
  refusalAt,
  removalObjectSchema,
  removalPreviewSchema,
  valueOf,
  type EnvDryRunCount,
  type EnvFileRefusal,
  type EnvRunCount,
} from './common.js';

/** The script a `seed` resource runs. */
export const SEED_SCRIPT = 'sandforge-seed' satisfies RunnableScript;

// ─── The resource, converted ─────────────────────────────────────────────────

/**
 * What a seed resource runs, checked: its built-in template's content, or its
 * objects and relations as a template, held to Seed's own payload schema and
 * validator, their refusals said where the file wrote what they refuse.
 */
export function seedRunOfResource(
  env: string,
  name: string,
  resource: EnvSeedResource,
  now: Date,
): { run: EnvSeedRun; warnings: EnvFileRefusal[] } | { refusals: EnvFileRefusal[] } {
  const converted = seedRunOf(env, name, resource, now);
  if ('refusal' in converted) return { refusals: [converted.refusal] };
  const checked = checkSeedRun(name, resource, converted.run);
  if (checked.refusals.length > 0) return { refusals: checked.refusals };
  return { run: converted.run, warnings: checked.warnings };
}

/**
 * What a seed resource runs: its built-in template's content, or its objects
 * and relations as a template, in list order, each object's rules as the
 * panel saves them.
 */
function seedRunOf(
  env: string,
  name: string,
  resource: EnvSeedResource,
  now: Date,
): { run: EnvSeedRun } | { refusal: EnvFileRefusal } {
  const at = now.toISOString();
  const named = {
    id: `env-${env}-${name}`,
    name: `${env}/${name}`,
    description: `The ${name} resource of the ${env} environment`,
    version: 1,
    tags: ['sandforge-env'],
    createdAt: at,
    updatedAt: at,
  };
  let template: SeedTemplate;
  const draws: EnvSeedDraw[] = [];
  if (resource.template !== undefined) {
    const builtIn = PREBUILT_SEED_TEMPLATES.find((t) => t.id === resource.template);
    if (builtIn === undefined) {
      return {
        refusal: refusalAt(
          ['resources', name, 'template'],
          `there is no built-in template "${resource.template}": there is ` +
            `${PREBUILT_SEED_TEMPLATES.map((t) => t.id).join(', ')}`,
        ),
      };
    }
    template = {
      ...named,
      strategy: builtIn.strategy,
      objects: structuredClone(builtIn.objects),
      ...(builtIn.relations !== undefined ? { relations: structuredClone(builtIn.relations) } : {}),
    };
  } else {
    template = {
      ...named,
      strategy: 'faker',
      objects: (resource.objects ?? []).map((object, index) => ({
        objectApiName: object.object,
        recordCount: object.count,
        fieldRules: structuredClone(object.fields ?? []),
        excludedFields: [],
        insertOrder: index,
        // The panel's default, which `seedObjectConfigSchema` gives a saved object.
        batchSize: object.batchSize ?? 200,
      })),
      ...(resource.relations !== undefined
        ? {
            relations: resource.relations.flatMap((relation, at) => {
              const from = relation.parents.from;
              if (from === undefined) return [relationOf(relation)];
              const { childObject, lookupField, parentObject, distribution } = relationOf(relation);
              draws.push({
                at,
                relation: { childObject, lookupField, parentObject, distribution },
                from: from.split('.')[0] ?? from,
                ...(relation.parents.limit !== undefined ? { limit: relation.parents.limit } : {}),
              });
              return [];
            }),
          }
        : {}),
    };
  }
  const recordTypes = Object.fromEntries(
    (resource.objects ?? [])
      .filter((object) => object.recordTypes !== undefined)
      .map((object) => [object.object, [...new Set(object.recordTypes)]]),
  );
  return {
    run: {
      template,
      ...(resource.locale !== undefined ? { locale: resource.locale } : {}),
      ...(resource.seed !== undefined ? { seed: resource.seed } : {}),
      ...(Object.keys(recordTypes).length > 0 ? { recordTypes } : {}),
      acceptAutomation: resource.accept?.automation === true,
      ...(draws.length > 0 ? { draws } : {}),
    },
  };
}

/** The object a relation's parents are of: `object`, or the one `from` names after its resource. */
function parentObjectOf(parents: EnvSeedParents): string {
  return parents.object ?? parents.from?.split('.')[1] ?? '';
}

function relationOf(relation: NonNullable<EnvSeedResource['relations']>[number]): SeedRelation {
  const [childObject = '', lookupField = ''] = relation.lookup.split('.');
  const existing = relation.parents.existing;
  return {
    childObject,
    lookupField,
    parentObject: parentObjectOf(relation.parents),
    parents:
      existing === undefined
        ? { kind: 'generated' }
        : {
            kind: 'existing',
            ...(existing.where !== undefined ? { where: existing.where } : {}),
            limit: existing.limit,
          },
    distribution: relation.distribution,
  };
}

/**
 * The parents a draw stands in with where its ids are not known: what the org
 * holds of the parent object, read as a relation reads existing parents, as
 * many as it may draw. What the template is checked with, and what a dry run
 * reads before the resource it draws from has run, whose records nobody
 * knows yet; never what a run is given.
 */
function standInOf(draw: EnvSeedDraw): SeedRelation['parents'] {
  return { kind: 'existing', limit: draw.limit ?? SEED_RELATION_LIMITS.maxExistingParents };
}

/** A resource's relations in the order the file lists them: its own, and its draws with `parentsOf`. */
function relationsWithDraws(
  run: EnvSeedRun,
  parentsOf: (draw: EnvSeedDraw) => SeedRelation['parents'],
): SeedRelation[] {
  const own = [...(run.template.relations ?? [])];
  const draws = run.draws ?? [];
  const out: SeedRelation[] = [];
  for (let at = 0; at < own.length + draws.length; at++) {
    const draw = draws.find((each) => each.at === at);
    const next = draw !== undefined ? { ...draw.relation, parents: parentsOf(draw) } : own.shift();
    if (next !== undefined) out.push(next);
  }
  return out;
}

/**
 * The template a seed resource's dry run or run is given: its own, and each
 * draw's relation in its place, its parents the ids of the records the
 * resource it draws from created (`drawn`, by the draw's place). A draw whose
 * ids are not known stands in with what the org holds of the parent object
 * (`standIns`, a dry run's alone); a run is never given one.
 *
 * @throws When a draw's ids are not known and stand-ins are not allowed.
 */
export function seedTemplateOf(
  run: EnvSeedRun,
  drawn: ReadonlyMap<number, readonly string[]> | undefined,
  options: { standIns: boolean },
): SeedTemplate {
  if ((run.draws ?? []).length === 0) return run.template;
  return {
    ...run.template,
    relations: relationsWithDraws(run, (draw) => {
      const ids = drawn?.get(draw.at);
      if (ids !== undefined && ids.length > 0) return { kind: 'records', ids: [...ids] };
      if (!options.standIns) {
        throw new Error(
          `The relation on ${draw.relation.childObject}.${draw.relation.lookupField} draws its ` +
            `parents from ${draw.from}, whose records are not known: plan again.`,
        );
      }
      return standInOf(draw);
    }),
  };
}

/** The locales the seed's command line draws in. */
const SEED_LOCALES: readonly string[] = Object.keys(LOCALE_DATA);

/**
 * Hold a converted seed run to Seed's own payload schema and validator: their
 * refusals, said where the file wrote what they refuse.
 */
function checkSeedRun(
  name: string,
  resource: EnvSeedResource,
  run: EnvSeedRun,
): { refusals: EnvFileRefusal[]; warnings: EnvFileRefusal[] } {
  const base: EnvDocumentPath = ['resources', name];
  // Checked whole, each draw in its place: its lookup, its distribution and
  // its child are Seed's to judge, its parents read of the org standing in.
  const checking = seedTemplateOf(run, undefined, { standIns: true });
  const payload = seedTemplatePayloadSchema.safeParse(checking);
  if (!payload.success) {
    return {
      refusals: payload.error.issues.map((issue) =>
        refusalAt(filePathOf(base, resource, issue.path as EnvDocumentPath), issue.message),
      ),
      warnings: [],
    };
  }
  const validation = new SeedValidator().validate(checking);
  const said = ({ field, message }: { field: string; message: string }): EnvFileRefusal =>
    refusalAt(validatorPathOf(base, resource, checking, field), message);
  // The seed's command line draws in the locales it has data for, and
  // refuses any other before it reads the org: met at the plan's dry run, it
  // is met here instead.
  const locale =
    run.locale !== undefined && !SEED_LOCALES.includes(run.locale)
      ? [
          refusalAt(
            [...base, 'locale'],
            `the seed draws in ${SEED_LOCALES.join(', ')}, not ${run.locale}: name one of them, ` +
              'or leave locale out to draw in the org’s own',
          ),
        ]
      : [];
  return {
    refusals: [...validation.errors.map(said), ...locale],
    warnings: validation.warnings.map(said),
  };
}

/** Where the file wrote what a path of the converted template names. */
function filePathOf(
  base: EnvDocumentPath,
  resource: EnvSeedResource,
  path: EnvDocumentPath,
): EnvDocumentPath {
  if (resource.template !== undefined) return [...base, 'template'];
  const [list, index, key, ...rest] = path;
  if (list === 'objects' && typeof index === 'number') {
    const at = [...base, 'objects', index];
    if (key === 'objectApiName') return [...at, 'object'];
    if (key === 'recordCount') return [...at, 'count'];
    if (key === 'fieldRules') return [...at, 'fields', ...rest];
    return key === undefined ? at : [...at, key];
  }
  if (list === 'relations' && typeof index === 'number') {
    const at = [...base, 'relations', index];
    if (key === 'childObject' || key === 'lookupField') return [...at, 'lookup'];
    if (key === 'parentObject') return [...at, 'parents', 'object'];
    if (key === 'parents') return [...at, 'parents', 'existing', ...rest];
    return key === undefined ? at : [...at, key, ...rest];
  }
  return base;
}

/**
 * Where the file wrote what the seed validator names, as `objects[Account]`,
 * `objects[Account].fieldRules[Industry]` or `relations[Contact.AccountId]`.
 */
function validatorPathOf(
  base: EnvDocumentPath,
  resource: EnvSeedResource,
  template: SeedTemplate,
  field: string,
): EnvDocumentPath {
  if (resource.template !== undefined) return [...base, 'template'];
  const object = /^objects\[([^\]]+)\](?:\.fieldRules\[([^\]]+)\])?/.exec(field);
  if (object !== null) {
    const index = template.objects.findIndex((o) => o.objectApiName === object[1]);
    if (index < 0) return base;
    const rule = object[2];
    const ruleIndex =
      rule === undefined
        ? -1
        : (template.objects[index]?.fieldRules ?? []).findIndex((r) => r.fieldApiName === rule);
    return ruleIndex < 0
      ? [...base, 'objects', index]
      : [...base, 'objects', index, 'fields', ruleIndex];
  }
  const relation = /^relations\[([^\]]+)\]/.exec(field);
  if (relation !== null) {
    const index = (template.relations ?? []).findIndex(
      (r) => `${r.childObject}.${r.lookupField}` === relation[1],
    );
    return index < 0 ? base : [...base, 'relations', index];
  }
  return base;
}

/**
 * What a seed run writes, and nothing else: the fingerprint of a resource is
 * of this. A built-in template is its content, not its id, so a SandForge
 * whose template changed replaces what the old one wrote. The template's own
 * name, dates and tags, and each object's batch size, change no record.
 */
export function seedWritten(run: EnvSeedRun): Record<string, unknown> {
  const { template } = run;
  return {
    kind: 'seed',
    kindVersion: 1,
    strategy: template.strategy,
    objects: template.objects.map((object) => ({
      objectApiName: object.objectApiName,
      recordCount: object.recordCount,
      recordTypeId: object.recordTypeId,
      fieldRules: object.fieldRules,
      excludedFields: object.excludedFields,
      insertOrder: object.insertOrder,
    })),
    relations: template.relations ?? [],
    locale: run.locale ?? null,
    seed: run.seed ?? null,
    recordTypes: run.recordTypes ?? {},
    // The relations whose parents another resource created, as the file
    // gives them: what they draw changes with that resource, whose
    // fingerprint the resource's is chained to.
    draws: run.draws,
  };
}

/** The objects a seed resource writes, with the file's count of each: what `validate` lists. */
export function seedObjectsOf(run: EnvSeedRun): Array<{ object: string; count: number }> {
  return run.template.objects.map((object) => ({
    object: object.objectApiName,
    count: object.recordCount,
  }));
}

/**
 * The objects of a resource whose records hang from records the org holds
 * before its run — the children of a relation to `existing` parents, and
 * what the template writes under those — with the file's count of each.
 * What its dry run counts of these, it counts from what the org held when it
 * read it; every other object it counts from the file alone, and exactly: a
 * resource's contacts under its own accounts were given the file's six too,
 * of which its dry run had rightly counted two.
 */
export function seedDrawnCounts(run: EnvSeedRun): Map<string, number> {
  const { template } = run;
  const relations = relationsWithDraws(run, standInOf);
  // A draw's parents, before the resource it draws from has run, stand in
  // as parents the org holds: counted the same way.
  const drawn = new Set(
    relations
      .filter((relation) => relation.parents.kind === 'existing')
      .map((relation) => relation.childObject),
  );
  for (let grew = true; grew;) {
    grew = false;
    for (const object of template.objects) {
      if (drawn.has(object.objectApiName)) continue;
      if (seedDependencies(object, relations).some((parent) => drawn.has(parent))) {
        drawn.add(object.objectApiName);
        grew = true;
      }
    }
  }
  return new Map(
    template.objects
      .filter((object) => drawn.has(object.objectApiName))
      .map((object) => [object.objectApiName, object.recordCount]),
  );
}

// ─── The lines ───────────────────────────────────────────────────────────────

/**
 * What a seed resource's run, or its dry run, is given. Nothing of it
 * accepts automation: a seed's run refuses past the emails its records send,
 * which no acceptance lifts, and reads no `--accept-automation` — given one,
 * it refused the whole line. Its removal takes one.
 */
export interface SeedRunLine {
  /** sf CLI alias of the org the environment is applied to. */
  target: string;
  /** The `SeedTemplate` the resource converts into, written to a file. */
  templateFile: string;
  /** The run's id, of the environment's making (`env-…`). */
  runId: string;
  /** What the run's draws are seeded with: the same records, run after run. */
  seed?: number;
  /** The locale the faker draws in; the org's own when absent. */
  locale?: string;
  /** Record types by object, by DeveloperName: `EnvSeedRun.recordTypes`. */
  recordTypes?: Readonly<Record<string, readonly string[]>>;
}

/** What a run and its dry run are given alike: the same records, planned then written. */
function seedRunSwitches(input: SeedRunLine): string[] {
  return [
    '--target',
    valueOf('--target', input.target),
    '--template-file',
    valueOf('--template-file', input.templateFile),
    '--run-id',
    valueOf('--run-id', input.runId),
    ...(input.seed !== undefined ? ['--seed', String(input.seed)] : []),
    ...(input.locale !== undefined ? ['--locale', valueOf('--locale', input.locale)] : []),
    ...Object.entries(input.recordTypes ?? {}).flatMap(([object, names]) => [
      '--record-type',
      valueOf('--record-type', `${object}=${names.join(',')}`),
    ]),
  ];
}

/** The line of a seed resource's run, its summary alone on stdout. */
export function seedApplyLine(input: SeedRunLine): string[] {
  return [
    ...seedRunSwitches(input),
    '--json',
    // A run that wrote some records and had others refused is partial: the
    // environment holds it to every record it planned.
    '--fail-on-partial',
  ];
}

/** The line of a seed resource's dry run: the same template, read and planned, nothing written. */
export function seedDryRunLine(input: SeedRunLine): string[] {
  return [...seedRunSwitches(input), '--dry-run', '--json'];
}

/** What the removal of a seed resource's run, or its preview, is given. */
export interface SeedRemovalLine {
  /** sf CLI alias of the org the run wrote to. */
  target: string;
  /** The summary the run printed with `--json`, saved by the environment. */
  summary: string;
  /** Take the records changed since the run too. */
  includeChanged?: boolean;
  /** Delete although the target runs automation as the records go. */
  acceptAutomation?: boolean;
  /** Remove the rest when the user may not delete some objects' records. */
  leaveUndeletable?: boolean;
}

/** The switches a removal and its preview share. */
function removalSwitches(input: SeedRemovalLine): string[] {
  return [
    ...(input.includeChanged === true ? ['--include-changed'] : []),
    ...(input.acceptAutomation === true ? ['--accept-automation'] : []),
    ...(input.leaveUndeletable === true ? ['--leave-undeletable'] : []),
  ];
}

/** The line of the removal of a seed resource's run, its outcome alone on stdout. */
export function seedRemoveLine(input: SeedRemovalLine & { sweep?: boolean }): string[] {
  return [
    '--remove',
    valueOf('--remove', input.summary),
    '--target',
    valueOf('--target', input.target),
    ...removalSwitches(input),
    ...(input.sweep === true ? ['--sweep'] : []),
    '--json',
  ];
}

/** The line of the preview of that removal: what it would do, nothing written. */
export function seedPreviewLine(input: SeedRemovalLine): string[] {
  return [
    '--remove',
    valueOf('--remove', input.summary),
    '--target',
    valueOf('--target', input.target),
    '--preview',
    ...removalSwitches(input),
    '--json',
  ];
}

// ─── The answers ─────────────────────────────────────────────────────────────

/** One daily email limit the records send against, as the seed's gate counted it. */
const emailCheckSchema = z.object({
  limit: z.enum(['SingleEmail', 'DailyWorkflowEmails']),
  emails: countSchema,
  verdict: z.enum(['fits', 'exceeds', 'unread']),
  remaining: z.number().int().optional(),
  max: z.number().int().optional(),
  unread: z.string().optional(),
});

/** What the records make the target send, against what it has left today. */
const emailsSchema = z.object({
  checks: z.array(emailCheckSchema),
  refusal: z.string().optional(),
  unknown: z.array(z.string()).optional(),
});

/** One object of a seed's result. */
const seedObjectResultSchema = (ids: z.ZodType<string>) =>
  z.object({
    objectApiName: z.string().min(1),
    recordsCreated: countSchema,
    recordsFailed: countSchema,
    createdIds: z.array(ids),
    errors: z.array(z.string()),
    truncated: z.boolean().optional(),
  });

/** A seed's result: the orchestrator's, as the summary carries it. */
const seedResultSchema = (ids: z.ZodType<string>) =>
  z.object({
    templateId: z.string().optional(),
    operationId: z.string().min(1),
    status: z.enum(['success', 'partial', 'failure']),
    cancelled: z.boolean().optional(),
    objectResults: z.array(seedObjectResultSchema(ids)),
    totalRecordsCreated: countSchema,
    totalRecordsFailed: countSchema,
  });

/** What every seed summary says, run or dry run. */
const seedSummaryBase = {
  tool: z.literal(SEED_SCRIPT),
  target: z.string().min(1),
  seed: z.number().int().nonnegative(),
  startedAt: z.string().min(1),
  finishedAt: z.string().min(1),
  notes: z.array(z.string()).optional(),
  emails: emailsSchema,
  elapsedMs: countSchema,
  interrupted: z.literal(true).optional(),
};

/**
 * What `sandforge-seed --json` prints for a run that wrote: the records it
 * created by their ids, the org it wrote to, the file that keeps them.
 */
export const seedRunAnswerSchema = z.object({
  ...seedSummaryBase,
  dryRun: z.literal(false),
  /** Absent when the run created nothing, or the org did not say its id. */
  targetOrgId: idSchema.optional(),
  result: seedResultSchema(idSchema),
  /** Absent when the file could not be written: the summary is then what takes the run back. */
  runFile: z.string().min(1).optional(),
});

/** The data storage a dry run's records take, against what the target has left. */
const dryRunStorageSchema = z.object({
  bytes: countSchema,
  verdict: z.enum(['fits', 'near', 'exceeds', 'unread']),
  estimateMB: z.number().nonnegative(),
  maxMB: z.number().optional(),
  remainingMB: z.number().optional(),
  unread: z.string().optional(),
  /** What a real run would be refused for. */
  refusal: z.string().optional(),
});

/** The API requests a dry run's writes would make, against what the target has left today. */
const dryRunApiRequestsSchema = z.object({
  estimate: countSchema,
  verdict: z.enum(['fits', 'near', 'exceeds', 'unread']),
  max: z.number().int().optional(),
  remaining: z.number().int().optional(),
  unread: z.string().optional(),
  /** What a real run would be refused for. */
  refusal: z.string().optional(),
});

/**
 * What `sandforge-seed --dry-run --json` prints: the records a run would
 * create, per object — counted, with stand-ins for ids (`dry-0`, …) — the
 * emails they would make the target send, and the data storage and API
 * requests they would take, as the gates counted them. Nothing it names is
 * in the org.
 */
export const seedDryRunAnswerSchema = z.object({
  ...seedSummaryBase,
  dryRun: z.literal(true),
  storage: dryRunStorageSchema,
  apiRequests: dryRunApiRequestsSchema,
  result: seedResultSchema(z.string()),
});

/**
 * What `sandforge-seed --remove … --json` prints once a removal ran: how it
 * ended, and per object what it deleted, found gone, kept and was refused.
 * A removal refused before its first delete prints nothing on stdout.
 */
export const seedRemovalAnswerSchema = z.object({
  tool: z.literal(SEED_SCRIPT),
  action: z.literal('remove'),
  summary: z.string().min(1),
  target: z.string().min(1),
  includeChanged: z.boolean(),
  result: z.object({
    status: z.enum(['success', 'partial', 'failure', 'cancelled']),
    planned: countSchema,
    objects: z.array(removalObjectSchema),
    sweep: z.object({ status: z.string() }).loose().optional(),
  }),
  elapsedMs: countSchema,
});

/**
 * What `sandforge-seed --remove … --preview --json` prints: per object, what
 * a removal would delete, keep, leave and not find, and what it would be
 * refused for now. It wrote nothing.
 */
export const seedPreviewAnswerSchema = z.object({
  tool: z.literal(SEED_SCRIPT),
  action: z.literal('remove-preview'),
  summary: z.string().min(1),
  target: z.string().min(1),
  includeChanged: z.boolean(),
  preview: removalPreviewSchema,
  refusals: z.array(z.string()),
  notes: z.array(z.string()),
  elapsedMs: countSchema,
});

export type SeedRunAnswer = z.infer<typeof seedRunAnswerSchema>;
export type SeedDryRunAnswer = z.infer<typeof seedDryRunAnswerSchema>;
export type SeedPreviewAnswer = z.infer<typeof seedPreviewAnswerSchema>;
export type SeedRemovalAnswer = z.infer<typeof seedRemovalAnswerSchema>;

/** What a seed resource's run printed, read: see {@link seedRunAnswerSchema}. */
export function readSeedRun(stdout: string): SeedRunAnswer {
  return readAnswer(SEED_SCRIPT, 'the summary of a run', seedRunAnswerSchema, stdout);
}

/** What a seed resource's dry run printed, read: see {@link seedDryRunAnswerSchema}. */
export function readSeedDryRun(stdout: string): SeedDryRunAnswer {
  return readAnswer(SEED_SCRIPT, 'the summary of a dry run', seedDryRunAnswerSchema, stdout);
}

/** What the preview of a seed run's removal printed, read: see {@link seedPreviewAnswerSchema}. */
export function readSeedPreview(stdout: string): SeedPreviewAnswer {
  return readAnswer(SEED_SCRIPT, 'the preview of a removal', seedPreviewAnswerSchema, stdout);
}

/** What the removal of a seed run printed, read: see {@link seedRemovalAnswerSchema}. */
export function readSeedRemoval(stdout: string): SeedRemovalAnswer {
  return readAnswer(SEED_SCRIPT, 'the outcome of a removal', seedRemovalAnswerSchema, stdout);
}

// ─── The answers, as the plan and the apply read every kind's ────────────────

/**
 * The object the seed's orchestrator names the result of a template it
 * refuses before its first insert: its validator's refusals, or parents
 * named by id the org no longer holds (`buildFailureResult`).
 */
const REFUSED_BEFORE_WRITING = 'validation';

/**
 * What a seed's dry run counted. Where it read the org before what an object
 * draws from was written, the file's count stands in, as the most the run
 * writes: the dry run counted none of those records, and the plan said
 * "Contact 0 to write" of a run that wrote three; given the file's count as
 * a count, it said "Contact 6 to write" of a run whose relation spread two
 * over the two accounts written before it.
 *
 * A dry run the seed refused before it would write — parents named by id no
 * longer in the org, which it checks before its first write — is the refusal
 * a run would meet, in the seed's words: read as counts, the plan said
 * "replace" of a resource whose run then wrote nothing. The orchestrator
 * answers such a refusal as one result of no object of the template
 * ({@link REFUSED_BEFORE_WRITING}), its refusals the errors of it; a dry run
 * whose objects were skipped — no parent in the org yet — is not one.
 *
 * @param drawn - The objects whose records hang from records written first
 *   in the same apply, with the file's count of each ({@link seedDrawnCounts}).
 */
export function seedDryRunCount(
  answer: SeedDryRunAnswer,
  drawn?: ReadonlyMap<string, number>,
): EnvDryRunCount {
  const results = answer.result.objectResults;
  if (
    answer.result.status === 'failure' &&
    results.length > 0 &&
    results.every((result) => result.objectApiName === REFUSED_BEFORE_WRITING)
  ) {
    const said = results.flatMap((result) => result.errors);
    return {
      objects: [],
      total: 0,
      created: 0,
      apiRequests: answer.apiRequests.estimate,
      storageBytes: 0,
      emails: [],
      refusal: said.length > 0 ? said.join(' ') : 'the seed refused its dry run',
    };
  }
  const objects = answer.result.objectResults.map((result) => {
    const most = drawn?.get(result.objectApiName);
    return most !== undefined
      ? {
          object: result.objectApiName,
          wouldCreate: Math.max(result.recordsCreated, most),
          atMost: true as const,
        }
      : { object: result.objectApiName, wouldCreate: result.recordsCreated };
  });
  const refusal = answer.storage.refusal ?? answer.apiRequests.refusal ?? answer.emails.refusal;
  return {
    objects,
    total: answer.result.totalRecordsCreated,
    created: answer.result.totalRecordsCreated,
    apiRequests: answer.apiRequests.estimate,
    storageBytes: answer.storage.bytes,
    emails: answer.emails.checks.map((check) => ({ limit: check.limit, emails: check.emails })),
    ...(refusal !== undefined ? { refusal } : {}),
  };
}

/** What a seed's run wrote, per object. */
export function seedRunCount(answer: SeedRunAnswer): EnvRunCount {
  return {
    objects: answer.result.objectResults.map((object) => ({
      object: object.objectApiName,
      created: object.recordsCreated,
      refused: object.recordsFailed,
      errors: object.errors,
    })),
    created: answer.result.totalRecordsCreated,
  };
}
